class Solution {
public:
    int sumImbalanceNumbers(vector<int>& nums) {
        int n = nums.size();
        int total = 0;
        for (int i = 0; i < n; ++i) {
            vector<bool> seen(n + 2, false);
            seen[nums[i]] = true;
            int cur = 0;
            for (int j = i + 1; j < n; ++j) {
                int x = nums[j];
                if (!seen[x]) {
                    bool has_prev = seen[x - 1];
                    bool has_next = seen[x + 1];
                    if (has_prev && has_next) cur--;
                    else if (!has_prev && !has_next) cur++;
                    seen[x] = true;
                }
                total += cur;
            }
        }
        return total;
    }
};

